            SvgDocument& rDocument,
            SvgNode* pParent)
        :   SvgNode(SVGToken::Use, rDocument, pParent),
            maSvgStyleAttributes(*this),
            mbDecomposingSvgNode(false)
        {
        }
SvgUseNode::~SvgUseNode()
        {
